  const lo = [...Z245_AUDIT.tensile].reverse().find(x=>x[0]<number);
  const hi = Z245_AUDIT.tensile.find(x=>x[0]>number);
  if (!lo || !hi) return null;
  const f=(number-lo[0])/(hi[0]-lo[0]);
